import{z as l,x as B,o as i,c as d,q as n,j as s,D as e,d as t,s as E,S as o,b as r}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"ping / iperf","description":"","frontmatter":{"title":"ping / iperf","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/network-measurement.md","filePath":"cs/network-measurement.md","lastUpdated":1791413859000}'),T={name:"cs/network-measurement.md"};function f(c,a,A,C,m,h){const p=B("Mermaid");return i(),d("div",null,[a[2]||(a[2]=n('<h1 id="ping-iperf" tabindex="-1">ping / iperf <a class="header-anchor" href="#ping-iperf" aria-label="Permalink to &quot;ping / iperf&quot;">​</a></h1><div class="epigraph"><p>ping 用 ICMP 回显读可达与 RTT；iperf 用灌流读吞吐。一个测延迟样本，一个填满 $C$，两者一起才对得上 BDP 与膨胀。</p><footer>—— 据 RFC 792 ICMP Echo；iperf 工具通识；Kurose 测量节整理</footer></div><p><a href="/cs/ttl-traceroute">traceroute</a> 画路径。<a href="/cs/bandwidth-delay-product">BDP</a> 与 <a href="/cs/bufferbloat">缓冲膨胀</a> 要数。<a href="/cs/service-discovery">上一课</a> 结束分发。缺口是<strong>主动测量入门</strong>：Echo 与灌流。本课不把抓包写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>口 up 不等于应用好。ping：RTT、丢、是否过滤。不能代表 TCP 吞吐。iperf：开窗口灌满，看 Gb/s，会制造膨胀与扰民。要同时看 ping 在灌流时是否炸——膨胀诊断。ECMP 下每次测量可能不同路。卫星：ping 已是数百毫秒下限。</p><p>不要把公网 iperf 当攻击。</p><p><span class="marginnote">ICMP 常被滤，TCP ping 变体存在。iperf3 是实现。本课钉方法。</span></p><p><span class="marginnote">数字实例：100 Mbps 链路接 50 ms 远的主机，BDP \\(= 100 \\times 10^6 \\text{ bit/s} \\times 0.05 \\text{ s} = 5 \\times 10^6\\) bit \\(\\approx 625\\) KB。iperf 的 TCP 窗口开不到这个量级时灌不满管道，测出的「带宽」会明显偏低——先查窗口再看链路。</span></p><h3 id="两把尺子" tabindex="-1">两把尺子 <a class="header-anchor" href="#两把尺子" aria-label="Permalink to &quot;两把尺子&quot;">​</a></h3><p>ping 看 RTT，iperf 看吞吐，合起来看队列。ICMP 可能被降级。单次结果受 ECMP 污染。要分布不要单点。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：控制面 traceroute / 数据面 ping / 灌流 iperf。画：空闲 RTT vs 负载 RTT。与 ABR 估计同类，一层工具。</p><p><span class="marginnote">术语翻译：RTT 就是用「发一个探测包、等对方回声」的手段来做「估计往返延迟与可达性」的事，类似对着山谷喊一声掐表等回音；iperf 则是反过来不停灌水，看管子每秒实际能过多少。</span></p>',13)),(i(),s(o,null,{default:e(()=>[E(p,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PING%5B%22ICMP%20Echo%22%5D%20--%3E%20RTT%5B%22%E5%BB%B6%E8%BF%9F%E6%A0%B7%E6%9C%AC%22%5D%0A%20%20IPERF%5B%22%E7%81%8C%E6%B5%81%22%5D%20--%3E%20THR%5B%22%E5%90%9E%E5%90%90%22%5D%0A%20%20BOTH%5B%22%E5%90%8C%E6%97%B6%22%5D%20--%3E%20BB%5B%22%E5%8F%91%E7%8E%B0%E8%86%A8%E8%83%80%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"QoS 可能把 ICMP 降级，ping 差而 TCP 好。RoCE 要用专门诊断。Maglev 后测量打到不同后端。DoH 不改 ping。权限：ping 要 raw socket 在某系统。",-1)),a[5]||(a[5]=r("p",null,"统计：一次 ping 无意义，要分布。",-1)),(i(),s(o,null,{default:e(()=>[E(p,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22iperf%20%E7%81%8C%E6%B5%81%E9%80%9F%E7%8E%87%22%5D%20--%3E%7C%22%E9%80%9F%E7%8E%87%20%5Cgt%20%E5%AE%B9%E9%87%8F%20C%22%7C%20Q%5B%22%E8%B7%AF%E7%94%B1%E5%99%A8%E7%BC%93%E5%86%B2%E9%98%9F%E5%88%97%E5%A2%9E%E9%95%BF%22%5D%0A%20%20S%20--%3E%7C%22%E9%80%9F%E7%8E%87%20%5Clt%20%E5%AE%B9%E9%87%8F%20C%22%7C%20OK%5B%22%E9%98%9F%E5%88%97%E5%87%A0%E4%B9%8E%E4%B8%BA%E7%A9%BA%22%5D%0A%20%20OK%20--%3E%20RTT1%5B%22%E7%A9%BA%E9%97%B2%20RTT%22%5D%0A%20%20Q%20--%3E%7C%22%E6%8E%92%E9%98%9F%E5%BB%B6%E8%BF%9F%E5%8F%A0%E5%8A%A0%22%7C%20RTT2%5B%22%E8%B4%9F%E8%BD%BD%20RTT%20%E5%A4%A7%E6%B6%A8%22%5D%0A%20%20RTT2%20--%3E%20R%5B%22%E7%A9%BA%E9%97%B2%2F%E8%B4%9F%E8%BD%BD%20RTT%20%E6%AF%94%E5%80%BC%E5%A4%A7%20%E2%87%92%20%E8%86%A8%E8%83%80%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p>这张图回答：为什么「负载下 ping 变炸」能诊断缓冲膨胀。灌流速率超过链路容量 \\(C\\) 时，多出的比特只能排在路由器缓冲里，每个包的 RTT 都被排队延迟撑高；空闲与负载两把 RTT 一比，膨胀就现形。</p><p><span class="marginnote">常见误区：初学者容易以为 ping 通就等于网络没问题。实际上 QoS 常把 ICMP 降级——ping 丢而 TCP 正常；反过来 TCP 卡而 ping 好也常见。单次 ping 更是纯噪声，要跑几十上百个样本看分位数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 OWAMP 的全部。抓包与 Wireshark 是下一课。后课默认：ping 看 RTT/可达；iperf 看吞吐；合起来看队列。</p><p>只报「带宽 1G」不报 RTT 是半张图。</p><p>下一课<a href="/cs/packet-capture">抓包与 Wireshark</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Echo 测延迟；灌流测吞吐。</li><li>负载下 ping 暴露膨胀。</li><li>过滤与 ECMP 使单次结果不可绝对化。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 792；测量实践。</li></ul>',8))])}const P=l(T,[["render",f]]);export{u as __pageData,P as default};
